window.kbPageData["views/entry/k-0a7afca718d2aa93"] = {"key":"entry/k-0a7afca718d2aa93","state":{"route":"entry/k-0a7afca718d2aa93"},"node":{"id":"k-0a7afca718d2aa93","mode":"k","title":"化解地方政府债务风险","type":"概念与词义","domain":"经济","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["finance"],"主类":["概念与词义"],"出处性质":["机构注释"],"学科":["经济"],"来源主题":["发展与治理"],"资料类别":["非时政"]},"directorySummary":"2.化解地方政府债务风险\n地方性政府债务指有财政收入的地方政府及地方公共机构发行的债券，是地方政府根据\n信用原则、以承担还本付息责任为前提而筹集资金的债务凭证，其收入列入地方政府预算并\n由地方政府安排调度。\n我国地方政府债务分为法定债务和隐性债务。\n（1）地方政府法定债务：是指地方政府在法定债务限额…","sources":[{"id":"7b62b3ebc327bd69","label":"化解地方政府债务风险","topic":"发展与治理","category":"非时政","text":"2.化解地方政府债务风险\n地方性政府债务指有财政收入的地方政府及地方公共机构发行的债券，是地方政府根据\n信用原则、以承担还本付息责任为前提而筹集资金的债务凭证，其收入列入地方政府预算并\n由地方政府安排调度。\n我国地方政府债务分为法定债务和隐性债务。\n（1）地方政府法定债务：是指地方政府在法定债务限额之内，通过发行债券举借的债\n务，包括一般债和专项债。\n（2）地方政府隐性债务：是指地方政府在法定政府债务限额之外，直接或者承诺以财\n政资金偿还，以及违规提供担保等方式举借的债务。\n——《我国地方政府债务合并监管研究》","source":{"doc":"6cbfb01fe723bba64b75","first":48,"last":48,"page":48,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"finance","title":"财政金融与宏观调控"}],"units":{"k-0a7afca718d2aa93":[]}};
